const READINESS_RANK: Record<ReportReadinessLevel, number> = {
  prep_draft: 0,
  readiness_assessment: 1,
  filing_ready: 2,
};

export const isExportFormatClientAllowed = (
  format: ReportingExportFormatOption,
  readinessLevel?: string | null
): boolean => {
  const level = (readinessLevel as ReportReadinessLevel) || 'prep_draft';
  return READINESS_RANK[level] >= READINESS_RANK[format.minReadinessLevel];
};

export const reportTypeForTab = (tabValue: number): string | null => {
  if (tabValue === REPORTING_TAB.BRSR) return 'brsr';
  if (tabValue === REPORTING_TAB.ISO_14064) return 'iso14064';
  if (!HIDE_ISO_14067_UI && tabValue === REPORTING_TAB.ISO_14067) return 'iso14067';
  if (tabValue === REPORTING_TAB.CBAM) return 'cbam';
  return null;
};

export const mapReportingDateRange = (reportType: string, dateRange: string): string => {
  const cbamPeriodMap: Record<string, string> = {
    '1month': 'month',
    '3months': 'quarter',
    '6months': 'half-year',
    '1year': 'year',
  };
  const standardPeriodMap: Record<string, string> = {
    '1month': 'month',
    '3months': 'quarter',
    '6months': '6months',
    '1year': 'annual',
  };
  if (reportType === 'cbam') {
    return cbamPeriodMap[dateRange] || 'quarter';
  }
  return standardPeriodMap[dateRange] || 'annual';
};

export const exportFormatsForTab = (tabValue: number): ReportingExportFormatOption[] => {
  const reportType = reportTypeForTab(tabValue);
  return reportType ? (REPORTING_EXPORT_FORMATS[reportType] || []) : [];
};

export const statutoryExportFormatsForTab = (tabValue: number): ReportingExportFormatOption[] =>
  exportFormatsForTab(tabValue).filter((format) => format.statutory);

export const defaultExportFileName = (
  reportType: string,
  format: ReportingExportFormatOption,
  companyName = 'MSME'
): string => {
  const safeCompany = companyName.replace(/[^a-z0-9-_]/gi, '_').slice(0, 50);
  const dateStamp = new Date().toISOString().slice(0, 10);
  return `${safeCompany}_${reportType.toUpperCase()}_${format.id}_${dateStamp}.${format.fileExtension}`;
};
